begin;
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('dd120000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.ok(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'plan admin: %',message;end if;end$$;
create function pg_temp.login(n integer,aal text default 'aal2') returns void language sql as $$select set_config('request.jwt.claim.sub',pg_temp.id(n)::text,true),set_config('request.jwt.claims',json_build_object('sub',pg_temp.id(n),'aal',aal)::text,true)$$;
create function pg_temp.state(q text) returns text language plpgsql as $$begin execute q;return 'OK';exception when others then return sqlstate;end$$;
insert into auth.users(id,email) select pg_temp.id(n),'plan-admin-'||n||'@example.test' from generate_series(1,4)n;
insert into public.user_roles(user_id,role) select pg_temp.id(n),case n when 1 then 'ADMIN' when 2 then 'STUDENT' when 3 then 'TEACHER' else 'SUPPORT' end from generate_series(1,4)n;
insert into public.plans(id,code,name,amount_cents,billing_interval) values(pg_temp.id(100),'PLAN_ADMIN_TEST','Plan test',12345,'MONTH');
insert into public.entitlements(id,key,description,unit) values(pg_temp.id(101),'plan_admin_boolean','Boolean capability','BOOLEAN');
insert into public.plan_entitlements(id,plan_id,entitlement_id,limit_value,cadence,effective_from)
 values(pg_temp.id(102),pg_temp.id(100),'20000000-0000-0000-0000-000000000001',1,'WEEK',now()-interval '1 day');
insert into public.subscriptions(user_id,plan_id,provider,status) values(pg_temp.id(2),pg_temp.id(100),'test','ACTIVE');
insert into public.teachers(id,user_id) values(pg_temp.id(103),pg_temp.id(3));
insert into public.live_sessions(id,teacher_id,session_type,title,starts_at,ends_at,capacity,required_entitlement_key)
 values(pg_temp.id(104),pg_temp.id(103),'CORE_CLASS','Plan history',now()+interval '4 days',now()+interval '4 days 45 minutes',6,'weekly_core_classes');
set local role authenticated;
select pg_temp.login(2,'aal1');
select public.book_live_session(pg_temp.id(104));
select pg_temp.ok(pg_temp.state('select public.admin_plan_list()')='42501','Student cannot list');
select pg_temp.ok(pg_temp.state('select public.admin_plan_set_entitlement(null,null,null,null,null)')='42501','Student cannot write even malformed input');
select pg_temp.login(3);
select pg_temp.ok(pg_temp.state('select public.admin_plan_list()')='42501','Teacher cannot list');
select pg_temp.ok(pg_temp.state('select public.admin_plan_set_entitlement(null,null,null,null,null)')='42501','Teacher cannot write');
select pg_temp.login(4);
select pg_temp.ok(pg_temp.state('select public.admin_plan_list()')='42501','Support cannot list');
select pg_temp.ok(pg_temp.state('select public.admin_plan_set_entitlement(null,null,null,null,null)')='42501','Support cannot write');
select pg_temp.login(1,'aal1');
select pg_temp.ok(pg_temp.state('select public.admin_plan_list()')='42501','Admin AAL1 cannot list');
select pg_temp.ok(pg_temp.state('select public.admin_plan_set_entitlement(null,null,null,null,null)')='42501','Admin AAL1 cannot write');
reset role;
create temp table booking_before as select to_jsonb(b) snapshot from public.session_bookings b where live_session_id=pg_temp.id(104);
select pg_temp.ok((select count(*)=1 from booking_before),'nonempty booking history fixture');
set local role anon;
select pg_temp.ok(pg_temp.state('select public.admin_plan_list()')='42501','anon cannot list');
select pg_temp.ok(pg_temp.state('select public.admin_plan_set_entitlement(null,null,null,null,null)')='42501','anon cannot write');
reset role;
set local role authenticated;
select pg_temp.login(1);
select pg_temp.ok(jsonb_typeof(public.admin_plan_list()->'versions')='array','Admin list contract');
select pg_temp.ok(pg_temp.state('update public.plans set amount_cents=1')='42501','no direct price DML');
select pg_temp.ok(pg_temp.state('update public.plan_entitlements set limit_value=2')='42501','no direct entitlement DML');
select public.admin_plan_set_entitlement(pg_temp.id(100),'20000000-0000-0000-0000-000000000001',2,'MONTH',now()+interval '1 day',jsonb_build_object('request_id',pg_temp.id(999),'environment','test','version','12d'));
select pg_temp.ok((public.admin_plan_set_entitlement(pg_temp.id(100),'20000000-0000-0000-0000-000000000001',2,'MONTH',now()+interval '1 day')->>'changed')='false','exact retry is idempotent');
select pg_temp.ok(pg_temp.state($q$select public.admin_plan_set_entitlement(pg_temp.id(100),'20000000-0000-0000-0000-000000000001',3,'WEEK',now()+interval '1 day')$q$)='23514','same timestamp with conflicting configuration fails');
select pg_temp.ok(pg_temp.state($q$select public.admin_plan_set_entitlement(pg_temp.id(100),'20000000-0000-0000-0000-000000000001',3,'WEEK',now()+interval '12 hours')$q$)='23514','cannot insert before pending open version');
select pg_temp.ok(pg_temp.state($q$select public.admin_plan_set_entitlement(pg_temp.id(100),pg_temp.id(101),2,'NONE',now()+interval '2 days')$q$)='23514','boolean must be binary');
select pg_temp.ok(pg_temp.state($q$select public.admin_plan_set_entitlement(pg_temp.id(100),pg_temp.id(101),1,'WEEK',now()+interval '2 days')$q$)='23514','boolean cannot recur');
select pg_temp.ok(pg_temp.state($q$select public.admin_plan_set_entitlement(pg_temp.id(100),pg_temp.id(101),1,'NONE',now()-interval '1 hour')$q$)='23514','past schedule denied');
select pg_temp.ok(pg_temp.state($q$select public.admin_plan_set_entitlement(pg_temp.id(100),'20000000-0000-0000-0000-000000000001',1.5,'WEEK',now()+interval '2 days')$q$)='23514','fractional count denied');
select pg_temp.ok(pg_temp.state($q$select public.admin_plan_set_entitlement(pg_temp.id(100),pg_temp.id(101),1,'NONE',now()+interval '2 days','{"request_id":"invalid"}')$q$)='22P02','late audit failure rolls transaction back');
select public.admin_plan_set_entitlement(pg_temp.id(100),pg_temp.id(101),1,'NONE',now()+interval '2 days');
select public.admin_plan_set_entitlement(pg_temp.id(100),'20000000-0000-0000-0000-000000000001',0,'WEEK',now()+interval '3 days');
reset role;
select pg_temp.ok((select effective_to=now()+interval '1 day' and limit_value=1 and cadence='WEEK' from public.plan_entitlements where id=pg_temp.id(102)),'old version ends exactly at transition without changing values');
select pg_temp.ok((select count(*)=3 from public.plan_entitlements where plan_id=pg_temp.id(100) and entitlement_id='20000000-0000-0000-0000-000000000001'),'ordered future chain and no duplicate retries');
select pg_temp.ok((select amount_cents=12345 from public.plans where id=pg_temp.id(100)),'price untouched');
select pg_temp.ok((select snapshot=to_jsonb(b) from booking_before,public.session_bookings b where live_session_id=pg_temp.id(104)),'all persisted booking fields and commercial snapshot unchanged');
select pg_temp.ok((select limit_value=1 and cadence='WEEK' from private.booking_entitlement(pg_temp.id(2),'weekly_core_classes',now())),'current right remains unchanged before schedule');
select pg_temp.ok((select limit_value=2 and cadence='MONTH' from private.booking_entitlement(pg_temp.id(2),'weekly_core_classes',now()+interval '1 day')),'boundary resolves next version with new cadence');
select pg_temp.ok((select limit_value=0 and cadence='WEEK' from private.booking_entitlement(pg_temp.id(2),'weekly_core_classes',now()+interval '3 days')),'later version resolves at boundary');
select pg_temp.ok((select count(*)=1 from public.audit_logs where action='entitlement_change' and request_id=pg_temp.id(999) and actor_user_id=pg_temp.id(1) and environment='test' and version='12d'),'correlated audit and no duplicate audit for retry');
select pg_temp.ok((select count(*)=1 from public.plan_entitlements where plan_id=pg_temp.id(100) and entitlement_id=pg_temp.id(101)),'failed audit left no partial version');
-- Exact retries of an effective version are read-only and remain safe after the boundary.
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true),set_config('request.jwt.claims',json_build_object('sub',pg_temp.id(1),'aal','aal2')::text,true);
set local role authenticated;
select pg_temp.ok((public.admin_plan_set_entitlement(pg_temp.id(100),'20000000-0000-0000-0000-000000000001',1,'WEEK',now()-interval '1 day')->>'changed')='false','historical exact retry does not mutate');
rollback;
